import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.qXLDknWC.js";const c=JSON.parse('{"title":"NanoGPT Usage Proxy (Self-Hosted Production)","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/nanogpt-usage-proxy.md","filePath":"configuration/nanogpt-usage-proxy.md"}'),i={name:"configuration/nanogpt-usage-proxy.md"};function n(r,e,l,h,p,d){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="nanogpt-usage-proxy-self-hosted-production" tabindex="-1">NanoGPT Usage Proxy (Self-Hosted Production) <a class="header-anchor" href="#nanogpt-usage-proxy-self-hosted-production" aria-label="Permalink to &quot;NanoGPT Usage Proxy (Self-Hosted Production)&quot;">​</a></h1><p>This page is <strong>only</strong> for people who build and host <strong>their own</strong> CharacterVault production site and want NanoGPT <strong>subscription status</strong> and <strong>weekly token</strong> details in Settings.</p><h2 id="you-almost-certainly-do-not-need-this" tabindex="-1">You almost certainly do not need this <a class="header-anchor" href="#you-almost-certainly-do-not-need-this" aria-label="Permalink to &quot;You almost certainly do not need this&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Situation</th><th style="text-align:left;">Need this worker?</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Using the official hosted app</strong></td><td style="text-align:left;"><strong>No.</strong> The public site already provides the proxy.</td></tr><tr><td style="text-align:left;"><strong>Running locally with <code>npm run dev</code></strong></td><td style="text-align:left;"><strong>No.</strong> Vite proxies NanoGPT usage for you automatically. Restart the dev server if something looks stale.</td></tr><tr><td style="text-align:left;"><strong><code>vite preview</code> / localhost production build</strong></td><td style="text-align:left;"><strong>No.</strong> Localhost can use the same Vite preview proxy path.</td></tr><tr><td style="text-align:left;"><strong>Self-hosting a production build</strong> (your own domain, static host, etc.)</td><td style="text-align:left;"><strong>Yes, if</strong> you want subscription status and weekly quotas. Balance and models still work without it.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Do not deploy this for localhost</p><p>If you only run CharacterVault with <code>npm run dev</code> on your machine, <strong>stop here</strong>. You do not need Cloudflare, Wrangler, or <code>VITE_NANOGPT_PROXY</code>.</p></div><h3 id="what-breaks-without-a-proxy-self-host-only" tabindex="-1">What breaks without a proxy (self-host only) <a class="header-anchor" href="#what-breaks-without-a-proxy-self-host-only" aria-label="Permalink to &quot;What breaks without a proxy (self-host only)&quot;">​</a></h3><ul><li><strong>Still works:</strong> API key, models list, balance (USD / Nano), chat, toolbar AI, sign-in</li><li><strong>May fail in the browser:</strong> subscription active / grace / inactive badge, weekly (and other) quota bars</li></ul><p>NanoGPT’s subscription usage API does not send browser CORS headers. A tiny proxy adds them. Balance and models do not need this.</p><hr><h2 id="when-you-are-self-hosting-production" tabindex="-1">When you <em>are</em> self-hosting production <a class="header-anchor" href="#when-you-are-self-hosting-production" aria-label="Permalink to &quot;When you *are* self-hosting production&quot;">​</a></h2><p>You need three things:</p><ol><li>The free Cloudflare Worker in this repo (<code>workers/nanogpt-usage-proxy/</code>)</li><li>Its public URL after deploy</li><li>That URL baked into your <strong>production build</strong> via <code>VITE_NANOGPT_PROXY</code></li></ol><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>A free <a href="https://www.cloudflare.com/" target="_blank" rel="noreferrer">Cloudflare</a> account</li><li>Node.js / npm (you already use these for CharacterVault)</li><li>The CharacterVault repo checked out on your machine</li></ul><h3 id="step-1-—-log-in-to-cloudflare-from-the-cli" tabindex="-1">Step 1 — Log in to Cloudflare from the CLI <a class="header-anchor" href="#step-1-—-log-in-to-cloudflare-from-the-cli" aria-label="Permalink to &quot;Step 1 — Log in to Cloudflare from the CLI&quot;">​</a></h3><p>From any directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>Complete the browser login when Wrangler opens it.</p><h3 id="step-2-—-deploy-the-worker" tabindex="-1">Step 2 — Deploy the worker <a class="header-anchor" href="#step-2-—-deploy-the-worker" aria-label="Permalink to &quot;Step 2 — Deploy the worker&quot;">​</a></h3><p>From the <strong>CharacterVault repo root</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workers/nanogpt-usage-proxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Wrangler prints a workers.dev URL, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://character-vault-nanogpt-usage.&lt;your-subdomain&gt;.workers.dev</span></span></code></pre></div><p>Copy the <strong>full</strong> URL (including <code>https://</code>). Do not use only the account subdomain root.</p><p>The worker only allows <code>GET /api/subscription/v1/usage</code>. It does not store API keys; it forwards your request headers and adds CORS.</p><h3 id="step-3-—-point-charactervault-at-the-worker-at-build-time" tabindex="-1">Step 3 — Point CharacterVault at the worker at build time <a class="header-anchor" href="#step-3-—-point-charactervault-at-the-worker-at-build-time" aria-label="Permalink to &quot;Step 3 — Point CharacterVault at the worker at build time&quot;">​</a></h3><p><code>VITE_NANOGPT_PROXY</code> must be set when you run the <strong>production</strong> build. Vite bakes it into the JS bundle. Setting it only in the shell after <code>npm run build</code> does nothing for an already-built site.</p><p><strong>Option A — <code>.env.production</code> (local builds)</strong></p><p>In the repo root (this file is typically gitignored):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_NANOGPT_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://character-vault-nanogpt-usage.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-subdomain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.workers.dev</span></span></code></pre></div><p>Then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><strong>Option B — CI / one-shot env</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VITE_NANOGPT_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://character-vault-nanogpt-usage.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your-subdomain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.workers.dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:VITE_NANOGPT_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://character-vault-nanogpt-usage.&lt;your-subdomain&gt;.workers.dev&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Use the exact URL Wrangler printed. No trailing slash required (CharacterVault normalizes it).</p><h3 id="step-4-—-deploy-your-dist-as-usual" tabindex="-1">Step 4 — Deploy your <code>dist/</code> as usual <a class="header-anchor" href="#step-4-—-deploy-your-dist-as-usual" aria-label="Permalink to &quot;Step 4 — Deploy your \`dist/\` as usual&quot;">​</a></h3><p>Upload or publish the new <code>dist/</code> output to <strong>your</strong> production host the way you already do (static host, reverse proxy, etc.).</p><h3 id="step-5-—-verify" tabindex="-1">Step 5 — Verify <a class="header-anchor" href="#step-5-—-verify" aria-label="Permalink to &quot;Step 5 — Verify&quot;">​</a></h3><ol><li>Open <strong>your</strong> self-hosted CharacterVault (not only localhost).</li><li><strong>Settings → AI Config → Nano-GPT</strong> with a valid key.</li><li>Open <strong>NanoGPT Account</strong>.</li><li>You should see balance <strong>and</strong> subscription status / quotas when NanoGPT returns them.</li><li>Use <strong>Refresh</strong> if you just deployed (respect the short cooldown).</li></ol><p>If balance works but subscription still errors, double-check:</p><ul><li>You rebuilt <strong>after</strong> setting <code>VITE_NANOGPT_PROXY</code></li><li>The deployed site is that new build</li><li>The worker URL opens and is the usage path (not a random workers.dev homepage)</li><li>Wrangler deploy succeeded and the worker name matches the URL</li></ul><hr><h2 id="optional-change-the-worker-name" tabindex="-1">Optional: change the worker name <a class="header-anchor" href="#optional-change-the-worker-name" aria-label="Permalink to &quot;Optional: change the worker name&quot;">​</a></h2><p>In <code>workers/nanogpt-usage-proxy/wrangler.toml</code>, <code>name</code> defaults to <code>character-vault-nanogpt-usage</code>. You can rename it before deploy; then use the new URL in <code>VITE_NANOGPT_PROXY</code>.</p><hr><h2 id="security-notes-short" tabindex="-1">Security notes (short) <a class="header-anchor" href="#security-notes-short" aria-label="Permalink to &quot;Security notes (short)&quot;">​</a></h2><ul><li>The worker only proxies one NanoGPT path.</li><li>It does not log or store your API key; keys pass through in request headers.</li><li>Prefer keeping the worker URL only in your private build env / CI secrets.</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup#nanogpt-account-overview">AI Setup → NanoGPT Account</a></li><li><a href="/CharacterVault/docs/getting-started/installation">Installation</a></li><li>Source: <code>workers/nanogpt-usage-proxy/</code> in the repository</li></ul>`,50)])])}const g=t(i,[["render",n]]);export{c as __pageData,g as default};
